import { useState } from 'preact/hooks';
import { HB_ROMAN } from '../../core';
import { useApp } from '../../data/store';
import { CaseProgress } from './Cases';
import { PhotoTimeline, PhotoMeasure } from '../components/photo';
import { caseById } from '../../cases/library';
import { AppBar, EstBadge, Segmented } from '../components/common';
import { Legend, LineChart, type Series } from '../components/LineChart';
import { Icon } from '../icons';
import { dayLabel, fmtDate } from '../labels';
import { showScales } from '../role';

export function Progress() {
  const { sessions, photos, profile, synk } = useApp();
  const scales = showScales(profile);
  const demoCase = profile?.demoCaseId ? caseById(profile.demoCaseId) : undefined;
  const caseRecords = demoCase ? photos.filter((p) => p.caseId === demoCase.id) : [];
  const [view, setView] = useState<'sessions' | 'photos'>(sessions.length === 0 && caseRecords.length ? 'photos' : 'sessions');
  const [sel, setSel] = useState('');
  const [metric, setMetric] = useState<'ffi' | 'composite'>('ffi');
  const [showTable, setShowTable] = useState(false);
  const scored = sessions.filter((s) => s.analysis.scores);
  const byDay = new Map(scored.map((s) => [s.daysSinceOnset, s]));

  const main: Series[] = [
    {
      id: metric,
      label: metric === 'ffi' ? '건강한 쪽 대비 움직임' : 'Sunnybrook 종합(추정)',
      color: 'var(--series-1)',
      points: scored.map((s) => ({
        x: s.daysSinceOnset,
        y: metric === 'ffi' ? s.analysis.scores!.functionIndex : s.analysis.scores!.composite,
      })),
    },
  ];
  const regions: Series[] = (
    [
      ['forehead', '이마', 'var(--series-1)'],
      ['eye', '눈', 'var(--series-2)'],
      ['midface', '코·볼', 'var(--series-3)'],
      ['mouth', '입', 'var(--series-4)'],
    ] as const
  ).map(([k, label, color]) => ({
    id: k,
    label,
    color,
    points: scored.map((s) => ({ x: s.daysSinceOnset, y: s.analysis.scores!.regional[k] })),
  }));

  const first = scored[0]?.analysis.scores;
  const last = scored[scored.length - 1]?.analysis.scores;

  return (
    <>
      <AppBar
        title="경과"
        sub={view === 'photos' ? `사진 ${caseRecords.length}장` : `평가 ${sessions.length}회`}
        right={
          sessions.length > 0 && (
            <a class="btn sm" href="#/report">
              <Icon name="clipboard" /> 의료진용 요약
            </a>
          )
        }
      />
      <main class="main">
        {synk.length > 0 && (
          <a class="card tight" href={`#/synk/${synk[synk.length - 1]!.id}`} style={{ textDecoration: 'none', color: 'inherit' }}>
            <div class="row between">
              <div>
                <b>연합운동 찾기 기록 {synk.length}회</b>
                <div class="xsmall ink2">함께 움직이는 곳 {synk.map((x) => x.result.findings.length).join(' → ')}군데 (오래된 순)</div>
              </div>
              <Icon name="chev" class="chev" />
            </div>
          </a>
        )}
        {caseRecords.length > 0 && (
          <Segmented
            label="기록 종류"
            value={view}
            onChange={setView}
            options={[
              { value: 'sessions', label: '동작 평가' },
              { value: 'photos', label: '사진 경과' },
            ]}
          />
        )}
        {view === 'photos' && demoCase ? (
          <>
            <PhotoTimeline records={caseRecords} selected={sel} onSelect={setSel} />
            {caseRecords.find((r) => r.id === sel) && (
              <div class="card tight">
                <PhotoMeasure record={caseRecords.find((r) => r.id === sel)!} />
                <a class="btn sm ghost" href={`#/case/${demoCase.id}`}>
                  측정 자세히 보기 <Icon name="chev" />
                </a>
              </div>
            )}
            <CaseProgress records={caseRecords} />
          </>
        ) : scored.length === 0 ? (
          <div class="card">
            <p class="ink2">아직 완료된 평가가 없습니다. 평가를 두 번 이상 하면 회복 추이를 볼 수 있습니다.</p>
            <a class="btn primary block" href="#/assess">
              평가 시작
            </a>
          </div>
        ) : (
          <>
            {first && last && scored.length > 1 && (
              <div class="tiles">
                <div class="tile">
                  <span class="label">움직임 (첫 평가 → 최근)</span>
                  <span class="value">
                    {first.functionIndex}→{last.functionIndex}
                    <small>%</small>
                  </span>
                </div>
                {scales && (
                  <div class="tile">
                    <span class="label">
                      HB 등급 <EstBadge />
                    </span>
                    <span class="value">
                      {HB_ROMAN[first.houseBrackmann.grade]}→{HB_ROMAN[last.houseBrackmann.grade]}
                    </span>
                  </div>
                )}
              </div>
            )}
            <div class="card">
              {scales && (
                <Segmented
                  label="지표 선택"
                  value={metric}
                  onChange={setMetric}
                  options={[
                    { value: 'ffi', label: '움직임 %' },
                    { value: 'composite', label: 'Sunnybrook' },
                  ]}
                />
              )}
              <h3>{main[0]!.label}</h3>
              <LineChart
                ariaLabel={`${main[0]!.label} 추이`}
                series={main}
                yMax={100}
                yTicks={[0, 25, 50, 75, 100]}
                ySuffix={metric === 'ffi' ? '%' : ''}
                xLabel={(x) => `${x}일`}
                xTitle="발병 후 일수"
                extra={(x) => {
                  const s = byDay.get(x);
                  if (s && !scales) return fmtDate(s.createdAt);
                  return s ? `HB ${HB_ROMAN[s.analysis.scores!.houseBrackmann.grade]}(추정) · ${fmtDate(s.createdAt)}` : null;
                }}
              />
            </div>
            <div class="card">
              <h3>부위별 움직임 (건강한 쪽 대비 %)</h3>
              <Legend series={regions} />
              <LineChart
                ariaLabel="부위별 움직임 추이"
                series={regions}
                yMax={100}
                yTicks={[0, 25, 50, 75, 100]}
                ySuffix="%"
                xLabel={(x) => `${x}일`}
                xTitle="발병 후 일수"
              />
              <button class="btn sm ghost" onClick={() => setShowTable(!showTable)} aria-expanded={showTable}>
                {showTable ? '표 닫기' : '표로 보기'}
              </button>
              {showTable && (
                <div class="table-scroll">
                  <table class="data">
                    <thead>
                      <tr>
                        <th>일수</th>
                        <th>움직임</th>
                        <th>SB</th>
                        <th>HB</th>
                        <th>이마</th>
                        <th>눈</th>
                        <th>코·볼</th>
                        <th>입</th>
                      </tr>
                    </thead>
                    <tbody>
                      {scored.map((s) => {
                        const c = s.analysis.scores!;
                        return (
                          <tr>
                            <td>{s.daysSinceOnset}</td>
                            <td>{c.functionIndex}</td>
                            <td>{c.composite}</td>
                            <td>{HB_ROMAN[c.houseBrackmann.grade]}</td>
                            <td>{c.regional.forehead}</td>
                            <td>{c.regional.eye}</td>
                            <td>{c.regional.midface}</td>
                            <td>{c.regional.mouth}</td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              )}
            </div>
          </>
        )}

        {view === 'sessions' && sessions.length > 0 && (
          <>
            <div class="section-title">평가 기록</div>
            <div class="card tight">
              <div class="list">
                {[...sessions].reverse().map((s) => (
                  <a class="list-item" href={`#/session/${s.id}`}>
                    <div class="grow">
                      <div>
                        {fmtDate(s.createdAt)} <span class="muted small">· {dayLabel(s.daysSinceOnset)}</span>
                      </div>
                      <div class="small ink2">
                        {s.analysis.scores
                          ? `움직임 ${s.analysis.scores.functionIndex}% · SB ${s.analysis.scores.composite} · HB ${HB_ROMAN[s.analysis.scores.houseBrackmann.grade]}`
                          : s.analysis.status === 'failed'
                            ? '측정 실패'
                            : '부분 측정'}
                        {s.mode === 'demo' ? ' · 데모' : s.mode === 'photo' ? ' · 사진' : ''}
                      </div>
                    </div>
                    <Icon name="chev" class="chev" />
                  </a>
                ))}
              </div>
            </div>
          </>
        )}
      </main>
    </>
  );
}
